namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<List<Shipment>> SearchShipmentsAsync(string? statusFilter, string? destinationFilter);
    Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber);
    Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<List<Shipment>> SearchShipmentsAsync(string? statusFilter, string? destinationFilter)
    {
        var query = "api/shipments?";
        if (!string.IsNullOrWhiteSpace(statusFilter))
            query += $"status={Uri.EscapeDataString(statusFilter)}&";
        if (!string.IsNullOrWhiteSpace(destinationFilter))
            query += $"destination={Uri.EscapeDataString(destinationFilter)}&";

        return await http.GetFromJsonAsync<List<Shipment>>(query.TrimEnd('&', '?')) ?? [];
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        try
        {
            return await http.GetFromJsonAsync<Shipment>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.NotFound)
        {
            return null;
        }
    }

    public async Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", newStatus);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

/// <summary>
/// Server-side in-memory shipment service with seed data.
/// Replace with EF Core / database access for production.
/// </summary>
public class ShipmentServerService : IShipmentService
{
    private readonly List<Shipment> _shipments;
    private readonly Lock _lock = new();
    private int _nextId;

    public ShipmentServerService()
    {
        _shipments = GenerateSeedData();
        _nextId = _shipments.Max(s => s.Id) + 1;
    }

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<List<Shipment>> SearchShipmentsAsync(string? statusFilter, string? destinationFilter)
    {
        lock (_lock)
        {
            var query = _shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(statusFilter)
                && Enum.TryParse<ShipmentStatus>(statusFilter, ignoreCase: true, out var status))
            {
                query = query.Where(s => s.Status == status);
            }

            if (!string.IsNullOrWhiteSpace(destinationFilter))
            {
                query = query.Where(s =>
                    s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase));
            }

            return Task.FromResult(query.ToList());
        }
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is null)
                return Task.FromResult<Shipment?>(null);

            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delayed)
                shipment.EstimatedDelivery = shipment.EstimatedDelivery.AddDays(2);

            return Task.FromResult<Shipment?>(shipment);
        }
    }

    private static List<Shipment> GenerateSeedData()
    {
        var now = DateTime.UtcNow;
        return
        [
            new() { Id = 1,  TrackingNumber = "SHP-1001", Origin = "New York, US",    Destination = "London, UK",        Status = ShipmentStatus.InTransit,      ShippedDate = now.AddDays(-3), EstimatedDelivery = now.AddDays(4),  CustomerEmail = "alice@example.com",  Description = "Electronics – 2 pallets" },
            new() { Id = 2,  TrackingNumber = "SHP-1002", Origin = "Shanghai, CN",     Destination = "Los Angeles, US",   Status = ShipmentStatus.PickedUp,       ShippedDate = now.AddDays(-1), EstimatedDelivery = now.AddDays(12), CustomerEmail = "bob@example.com",    Description = "Textiles – 1 container" },
            new() { Id = 3,  TrackingNumber = "SHP-1003", Origin = "Berlin, DE",       Destination = "Tokyo, JP",         Status = ShipmentStatus.Pending,        ShippedDate = now,             EstimatedDelivery = now.AddDays(8),  CustomerEmail = "carol@example.com",  Description = "Auto parts – 5 crates" },
            new() { Id = 4,  TrackingNumber = "SHP-1004", Origin = "São Paulo, BR",    Destination = "Miami, US",         Status = ShipmentStatus.OutForDelivery, ShippedDate = now.AddDays(-5), EstimatedDelivery = now,             CustomerEmail = "dave@example.com",   Description = "Coffee – 200 bags" },
            new() { Id = 5,  TrackingNumber = "SHP-1005", Origin = "Mumbai, IN",       Destination = "Dubai, AE",         Status = ShipmentStatus.Delivered,      ShippedDate = now.AddDays(-7), EstimatedDelivery = now.AddDays(-1), CustomerEmail = "eve@example.com",    Description = "Pharmaceuticals – cold chain" },
            new() { Id = 6,  TrackingNumber = "SHP-1006", Origin = "Sydney, AU",       Destination = "Singapore, SG",     Status = ShipmentStatus.Delayed,        ShippedDate = now.AddDays(-4), EstimatedDelivery = now.AddDays(3),  CustomerEmail = "frank@example.com",  Description = "Machinery – oversized" },
            new() { Id = 7,  TrackingNumber = "SHP-1007", Origin = "Toronto, CA",      Destination = "Mexico City, MX",   Status = ShipmentStatus.InTransit,      ShippedDate = now.AddDays(-2), EstimatedDelivery = now.AddDays(3),  CustomerEmail = "grace@example.com",  Description = "Food products – refrigerated" },
            new() { Id = 8,  TrackingNumber = "SHP-1008", Origin = "Paris, FR",        Destination = "Cairo, EG",         Status = ShipmentStatus.PickedUp,       ShippedDate = now,             EstimatedDelivery = now.AddDays(6),  CustomerEmail = "hank@example.com",   Description = "Fashion goods – fragile" },
        ];
    }
}

