            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<List<Shipment>> SearchShipmentsAsync(string? statusFilter, string? destinationFilter)
    {
        lock (_lock)
        {
            var query = _shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(statusFilter)
                && Enum.TryParse<ShipmentStatus>(statusFilter, ignoreCase: true, out var status))
            {
                query = query.Where(s => s.Status == status);
            }

            if (!string.IsNullOrWhiteSpace(destinationFilter))
            {
                query = query.Where(s =>
                    s.Destination.Contains(destinationFilter, StringComparison.OrdinalIgnoreCase));
            }

            return Task.FromResult(query.ToList());
        }
    }

    public Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus newStatus)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is null)
                return Task.FromResult<Shipment?>(null);

            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delayed)
                shipment.EstimatedDelivery = shipment.EstimatedDelivery.AddDays(2);

            return Task.FromResult<Shipment?>(shipment);
        }
    }

