@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">🚚 Dispatcher Dashboard</h2>

<div class="row mb-3 g-2">
    <div class="col-md-4">
        <label class="form-label">Filter by Status</label>
        <select class="form-select" @bind="statusFilter" @bind:after="ApplyFilters">
            <option value="">All Statuses</option>
            @foreach (var s in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@s">@s</option>
            }
        </select>
    </div>
    <div class="col-md-4">
        <label class="form-label">Filter by Destination</label>
        <input type="text" class="form-control" placeholder="e.g. London"
               @bind="destinationFilter" @bind:event="oninput" @bind:after="ApplyFilters" />
    </div>
    <div class="col-md-4 d-flex align-items-end">
        <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">No shipments match your filters.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Description</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in shipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>@s.Description</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered)
                            {
                                <select class="form-select form-select-sm" style="min-width:140px"
                                        @onchange="(e) => UpdateStatus(s.Id, e)">
                                    <option value="" selected disabled>Change…</option>
                                    @foreach (var ns in Enum.GetValues<ShipmentStatus>())
                                    {
                                        @if (ns != s.Status)
                                        {
                                            <option value="@ns">@ns</option>
                                        }
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">Complete</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
    <p class="text-muted">Showing @shipments.Count shipment(s)</p>
}

@code {
    private List<Shipment>? shipments;
    private string statusFilter = "";
    private string destinationFilter = "";

    protected override async Task OnInitializedAsync()
    {
        await ApplyFilters();
    }

    private async Task ApplyFilters()
    {
        shipments = await ShipmentService.SearchShipmentsAsync(
            string.IsNullOrWhiteSpace(statusFilter) ? null : statusFilter,
            string.IsNullOrWhiteSpace(destinationFilter) ? null : destinationFilter);
    }

    private async Task ClearFilters()
    {
        statusFilter = "";
        destinationFilter = "";
        await ApplyFilters();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (e.Value is string val && Enum.TryParse<ShipmentStatus>(val, out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(id, newStatus);
            await ApplyFilters();
        }
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending        => "bg-secondary",
        ShipmentStatus.PickedUp       => "bg-info text-dark",
        ShipmentStatus.InTransit      => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered      => "bg-success",
        ShipmentStatus.Delayed        => "bg-danger",
        _                             => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">🔍 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-1001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@searching">
                @if (searching)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Search
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        <strong>Not found.</strong> No shipment matches tracking number "<strong>@searchedNumber</strong>".
        Please check the number and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadge(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-5">Description</dt>
                <dd class="col-sm-7">@shipment.Description</dd>

                <dt class="col-sm-5">Origin</dt>
                <dd class="col-sm-7">@shipment.Origin</dd>

                <dt class="col-sm-5">Destination</dt>
                <dd class="col-sm-7">@shipment.Destination</dd>

                <dt class="col-sm-5">Shipped Date</dt>
                <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                <dt class="col-sm-5">Estimated Delivery</dt>
                <dd class="col-sm-7">
                    <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                    @if (shipment.Status == ShipmentStatus.Delivered)
                    {
                        <span class="text-success ms-2">✅ Delivered</span>
                    }
                    else
                    {
                        var daysLeft = (shipment.EstimatedDelivery.Date - DateTime.UtcNow.Date).Days;
                        if (daysLeft > 0)
                        {
                            <span class="text-muted ms-2">(@daysLeft day(s) away)</span>
                        }
                        else if (daysLeft == 0)
                        {
                            <span class="text-warning ms-2">(arriving today)</span>
                        }
                        else
                        {
                            <span class="text-danger ms-2">(@Math.Abs(daysLeft) day(s) overdue)</span>
                        }
                    }
                </dd>
            </dl>
        </div>

        @{
            var steps = GetProgressSteps(shipment.Status);
        }
        <div class="card-footer">
            <div class="d-flex justify-content-between text-center small">
                @foreach (var (label, active) in steps)
                {
                    <div>
                        <div class="@(active ? "text-primary fw-bold" : "text-muted")">
                            @(active ? "●" : "○")
                        </div>
                        <div class="@(active ? "fw-bold" : "")">@label</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private Shipment? shipment;
    private bool searched;
    private bool searching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static List<(string Label, bool Active)> GetProgressSteps(ShipmentStatus status)
    {
        var orderedStatuses = new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered };
        var currentIndex = status == ShipmentStatus.Delayed ? 2 : Array.IndexOf(orderedStatuses, status);
        return orderedStatuses.Select((s, i) => (s.ToString(), i <= currentIndex)).ToList();
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending        => "bg-secondary",
        ShipmentStatus.PickedUp       => "bg-info text-dark",
        ShipmentStatus.InTransit      => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered      => "bg-success",
        ShipmentStatus.Delayed        => "bg-danger",
        _                             => "bg-secondary"
    };
}

