                <dd class="col-sm-7">
                    <strong>@shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                    @if (shipment.Status == ShipmentStatus.Delivered)
                    {
                        <span class="text-success ms-2">✅ Delivered</span>
                    }
                    else
                    {
                        var daysLeft = (shipment.EstimatedDelivery.Date - DateTime.UtcNow.Date).Days;
                        if (daysLeft > 0)
                        {
                            <span class="text-muted ms-2">(@daysLeft day(s) away)</span>
                        }
                        else if (daysLeft == 0)
                        {
                            <span class="text-warning ms-2">(arriving today)</span>
                        }
                        else
                        {
                            <span class="text-danger ms-2">(@Math.Abs(daysLeft) day(s) overdue)</span>
                        }
                    }
                </dd>
            </dl>
        </div>

        @{
            var steps = GetProgressSteps(shipment.Status);
        }
        <div class="card-footer">
            <div class="d-flex justify-content-between text-center small">
                @foreach (var (label, active) in steps)
                {
                    <div>
                        <div class="@(active ? "text-primary fw-bold" : "text-muted")">
                            @(active ? "●" : "○")
                        </div>
                        <div class="@(active ? "fw-bold" : "")">@label</div>
                    </div>
                }
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private Shipment? shipment;
    private bool searched;
    private bool searching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetByTrackingNumberAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static List<(string Label, bool Active)> GetProgressSteps(ShipmentStatus status)
    {
        var orderedStatuses = new[] { ShipmentStatus.Pending, ShipmentStatus.PickedUp, ShipmentStatus.InTransit, ShipmentStatus.OutForDelivery, ShipmentStatus.Delivered };
        var currentIndex = status == ShipmentStatus.Delayed ? 2 : Array.IndexOf(orderedStatuses, status);
        return orderedStatuses.Select((s, i) => (s.ToString(), i <= currentIndex)).ToList();
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending        => "bg-secondary",
        ShipmentStatus.PickedUp       => "bg-info text-dark",
        ShipmentStatus.InTransit      => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered      => "bg-success",
        ShipmentStatus.Delayed        => "bg-danger",
        _                             => "bg-secondary"
    };
}

