arguments.new_str:
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;
using ShipmentTracker.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddSingleton<ShipmentServerService>();
builder.Services.AddScoped<IShipmentService>(sp => sp.GetRequiredService<ShipmentServerService>());

arguments.old_str:
// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

arguments.new_str:
// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

// Shipment API endpoints for WebAssembly clients
var shipmentApi = app.MapGroup("api/shipments").RequireAuthorization();

shipmentApi.MapGet("", async (string? status, string? destination, ShipmentServerService svc) =>
    await svc.SearchShipmentsAsync(status, destination));

shipmentApi.MapGet("track/{trackingNumber}", async (string trackingNumber, ShipmentServerService svc) =>
{
    var shipment = await svc.GetByTrackingNumberAsync(trackingNumber);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
}).AllowAnonymous();

shipmentApi.MapPut("{id:int}/status", async (int id, ShipmentStatus newStatus, ShipmentServerService svc) =>
{
    var shipment = await svc.UpdateStatusAsync(id, newStatus);
    return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
});

app.Run();

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp =>
    new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });
builder.Services.AddScoped<IShipmentService, ShipmentHttpService>();

await builder.Build().RunAsync();

